/* BYOH memstate harness for the github functional axis (batch 7).
 *
 * TARGET SIGNATURE:
 *   int twofish_keysize(int *keysize)   -- libtomcrypt src/ciphers/twofish/twofish.c
 *
 * WHY BYOH (not auto-generated): `func.c` here is the WHOLE twofish.c TU (not just our
 * target function), so a full link also drags in every OTHER function it defines
 * (twofish_setup/twofish_ecb_encrypt/twofish_ecb_decrypt/twofish_test/twofish_done). In
 * THIS build's active `LTC_ARGCHK` variant (tomcrypt_argchk.h's `do{if(!(x))
 * crypt_argchk(...);}while(0)` branch), those callers -- AND our own target,
 * `twofish_keysize` itself, via its own `LTC_ARGCHK(keysize)` -- reference `crypt_argchk`
 * (defined in libtomcrypt's separate src/misc/argchk.c, not vendored here); `twofish_test`
 * also references `ltc_compare_testvector` (src/misc/compare_testvector.c). Verified by
 * hand-compiling the plain auto-generated harness in the ddiv-oracle container:
 * link fails on exactly these two undefined symbols. `keysize` is always a valid non-NULL
 * pointer in this harness, so `crypt_argchk` (declared `LTC_NORETURN`) is NEVER actually
 * invoked at runtime by our own target; `ltc_compare_testvector` is reachable only from
 * `twofish_test`, which we never call either. Minimal, never-invoked, exact-signature
 * stand-ins (dead code in practice, exactly like `coreutils_file_name_concat.c`'s
 * `xalloc_die` stand-in) satisfy the linker without vendoring those sibling libtomcrypt TUs.
 *
 * PRECONDITIONS: `*keysize` is compared against 16/24/32 and clamped up to the next tier
 * (or rejected with CRYPT_INVALID_KEYSIZE if < 16). A uniform `vb_int()` draw (bounded
 * +-1000) would land in the ">=32" bucket ~48% of the time and the ">=32" branch's exact
 * fixed point (32) essentially never, so half of the draws are instead biased into a small
 * window around the three boundaries (-8..39) to exercise all four branches (INVALID,
 * ->16, ->24, ->32) with real probability.
 *
 * DISCRIMINATOR: CRYPT_OK==0 (checked in tomcrypt.h) and CRYPT_INVALID_KEYSIZE is a later,
 * nonzero enumerator, so a rejected draw (identity returns CRYPT_INVALID_KEYSIZE, `stub`
 * always returns 0) discriminates via the return value alone. An accepted draw discriminates
 * via `*keysize`'s POST-CALL content: identity overwrites it to the canonical 16/24/32,
 * while `stub` (a bare `return 0;`) leaves it at its original random fill -- which coincides
 * with the canonical value only in the negligible case the random fill was already exactly
 * 16/24/32 (an idempotent no-op for the real function too).
 *
 * Structure = funcharness.PRELUDE + <dead-code link stand-ins, see above> + MAIN_OPEN +
 * <middle> + HARNESS_FOOTER (verbatim). Contract: the seed is already in the VB_CUR/VB_N byte
 * cursor (MAIN_OPEN read argv[1]); build the in/out `keysize` int (biased near its three
 * boundaries) plus 7 more unused-but-folded filler ints, call the target once, fold its
 * return value + the whole array's post-call content into vb_digest, then vb_dump(argv[2]) &
 * exit 0. */
/* auto-generated by ddiv.funcharness -- DO NOT EDIT */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "func.c"

/* ---- program-exit memstate capture (see ddiv/functional.py) -----------------
 * Run func0 on a SAFE seed, fold its return value + any output buffers into a global
 * digest, then dump the program's own writable globals -- [.data, .bss], the part of
 * "all memory at program exit" that is deterministic across two independently-linked
 * binaries -- to argv[2]. The oracle byte-compares this dump to the frozen baseline:
 * equal => INTACT, differ-without-crash => silent VANISH, sanitizer/abort => DEVIATED. */

extern char __data_start[], _edata[], __bss_start[], _end[];

#define VB_MAXLEN   16     /* array length bound (paired T* arr, int n) */
#define VB_STRLEN   24     /* string length bound */
#define VB_INTBOUND 1000   /* scalar int magnitude bound */
#define VB_ARRLEN   8      /* default folded prefix for a lone array/pointer param */
#define VB_ARRCAP   256    /* generous zeroed allocation for a lone array/pointer param --
                            * modest over-reads by the original land on deterministic zeros;
                            * a read past the cap traps on the ORIGINAL build and the case is
                            * dropped by the safety/determinism filter (never a wrong verdict). */

static const unsigned char *VB_CUR; static long VB_N, VB_I;
static unsigned long vb_take(int nb){ unsigned long v=0; int k;
  for(k=0;k<nb;k++){ v |= (unsigned long)(VB_I<VB_N?VB_CUR[VB_I]:0) << (8*k); VB_I++; } return v; }
static long vb_int(void){ long m=2L*VB_INTBOUND+1; return (long)(vb_take(4)%m) - VB_INTBOUND; }
static double vb_dbl(void){ long x=(long)(vb_take(4)% (2000001UL)) - 1000000L; return (double)x/1000.0; }
static int vb_len(int bound){ return (int)(vb_take(1) % (unsigned)(bound+1)); }

/* result digest -- a global (lives in .data), so it is part of the dumped memstate.
 * FNV-1a over the function's return value + output buffers. */
static uint64_t vb_digest = 1469598103934665603ULL;
static void vb_mix(const void *p, unsigned long n){
  const unsigned char *b=(const unsigned char*)p; unsigned long i;
  for(i=0;i<n;i++){ vb_digest ^= b[i]; vb_digest *= 1099511628211ULL; } }
/* quantise a double to fixed-point (~1e-6 tolerance) so a numerically-equal result that
 * differs in the low mantissa bits (FMA / instruction-selection) still compares equal. */
static void vb_mix_d(double x){ long q;
  if(isnan(x)) q = (long)0x7ff8000000000000LL;
  else if(isinf(x)) q = (x>0?1:-1)*0x7fffffffffffffffLL;
  else q = (long)llround(x*1e6);
  vb_mix(&q, sizeof q); }
static void vb_mix_s(const char *s){
  if(!s){ unsigned char z=0; vb_mix(&z,1); return; }
  unsigned char nz=1; vb_mix(&nz,1); vb_mix(s, (unsigned long)strlen(s)); }

/* dump the program's writable globals (the deterministic part of the exit memstate). */
static void vb_dump(const char *path){
  VB_CUR=0; VB_N=0; VB_I=0;                  /* zero bookkeeping (VB_CUR holds a heap ptr) */
  if(!path) return;
  FILE *out = fopen(path, "wb"); if(!out) return;
  fwrite(__data_start, 1, (size_t)((char*)_edata   - (char*)__data_start), out);
  fwrite(__bss_start,  1, (size_t)((char*)_end     - (char*)__bss_start),  out);
  fclose(out); }

/* ---- dead-code link stand-ins (see file-header WHY BYOH comment) --------------------
 * `func.c` (the whole twofish.c TU) references these from functions unreachable from
 * `main` (which only ever calls twofish_keysize with a valid non-NULL pointer, so even
 * twofish_keysize's OWN `LTC_ARGCHK(keysize)` never actually fires). Signatures copied
 * verbatim from tomcrypt_argchk.h / tomcrypt_private.h (already `#include`d by func.c). */
void crypt_argchk(const char *v, const char *s, int d) { (void)v; (void)s; (void)d; abort(); }
int ltc_compare_testvector(const void *is, const unsigned long is_len, const void *should,
                           const unsigned long should_len, const char *what, int which) {
  (void)is; (void)is_len; (void)should; (void)should_len; (void)what; (void)which;
  return 0;
}

int main(int argc, char **argv){
  if(argc<2){ fprintf(stderr,"usage: %s <seed> [dump]\n", argv[0]); return 64; }
  FILE *fp=fopen(argv[1],"rb"); if(!fp){ perror("open"); return 64; }
  fseek(fp,0,SEEK_END); long fsz=ftell(fp); fseek(fp,0,SEEK_SET);
  unsigned char *buf=(unsigned char*)malloc(fsz>0?fsz:1);
  long nread=(long)fread(buf,1,fsz>0?fsz:0,fp); fclose(fp);
  VB_CUR=buf; VB_N=nread; VB_I=0;

  int a0_n = VB_ARRLEN;
  int *a0 = (int*)calloc(VB_ARRCAP, sizeof(int));
  /* a0[0] is the actual in/out `*keysize` scalar -- bias half the draws into a small window
   * around the three boundaries (16/24/32) so every branch (INVALID / ->16 / ->24 / ->32)
   * gets real coverage, instead of a broad uniform draw that lands >=32 nearly half the time
   * and the exact fixed points almost never. The rest (a0[1..7]) are unread by the target;
   * they are still folded below (matching the auto-generator's convention) as pure,
   * decompiler-invariant filler -- same seed => same fill on every decompiler variant, since
   * only the target function's body changes across splices, never this harness. */
  if (vb_take(1) % 2 == 0) {
    a0[0] = (int)(vb_take(1) % 48) - 8;      /* -8..39 */
  } else {
    a0[0] = (int)vb_int();                    /* full +-1000 range */
  }
  for (int _k = 1; _k < a0_n; _k++) { a0[_k] = (int)vb_int(); }

  long vb_ret = (long)(twofish_keysize(a0));
  vb_mix(&vb_ret, sizeof vb_ret);
  for (int _k = 0; _k < a0_n; _k++) { vb_mix(&a0[_k], sizeof a0[_k]); }

  vb_dump(argc>2?argv[2]:NULL);
  return 0;
}
